import{_ as o,a0 as r,w as p,s as d,I as e,x as s,a1 as a,A as n,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"匿名上網：學習在 Linux 上安裝 TOR 網絡 | LCTT x X-CMD","titleTemplate":false,"description":"匿名上網：學習在 Linux 上安裝 TOR 網絡 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"匿名上網：學習在 Linux 上安裝 TOR 網絡 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"匿名上網：學習在 Linux 上安裝 TOR 網絡 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171219 Surf anonymously- Learn to install TOR network on Linux","title":"匿名上網：學習在 Linux 上安裝 TOR 網絡","tag":"201801","desc":""},"relativePath":"201801/20171219 Surf anonymously- Learn to install TOR network on Linux.md","filePath":"[post].md"}'),u={name:"201801/20171219 Surf anonymously- Learn to install TOR network on Linux.md"};function h(g,t,b,k,c,f){const i=r("Link");return p(),d("div",null,[t[18]||(t[18]=e("h1",{id:"匿名上網-學習在-linux-上安裝-tor-網絡",tabindex:"-1"},[s("匿名上網：學習在 Linux 上安裝 TOR 網絡 "),e("a",{class:"header-anchor",href:"#匿名上網-學習在-linux-上安裝-tor-網絡","aria-label":"Permalink to “匿名上網：學習在 Linux 上安裝 TOR 網絡”"},"​")],-1)),t[19]||(t[19]=e("p",null,"Tor 網絡是一個用來保護你的互聯網以及隱私的匿名網絡。Tor 網絡是一組志願者運營的服務器。Tor 通過在由志願者運營的分佈式中繼系統之間跳轉來保護互聯網通信。這避免了人們窺探我們的網絡，他們無法瞭解我們訪問的網站或者用户身在何處，並且也可以讓我們訪問被屏蔽的網站。",-1)),t[20]||(t[20]=e("p",null,"在本教程中，我們將學習在各種 Linux 操作系統上安裝 Tor 網絡，以及如何使用它來配置我們的程序來保護通信。",-1)),e("p",null,[t[1]||(t[1]=s("推薦閲讀：",-1)),a(i,{href:"http://linuxtechlab.com/install-tor-browser-linux-ubuntu-centos/"},{default:n(()=>[...t[0]||(t[0]=[s("如何在 Linux 上安裝 Tor 瀏覽器（Ubuntu、Mint、RHEL、Fedora、CentOS）",-1)])]),_:1})]),t[21]||(t[21]=l(`<h3 id="centos-rhel-fedora" tabindex="-1">CentOS/RHEL/Fedora <a class="header-anchor" href="#centos-rhel-fedora" aria-label="Permalink to “CentOS/RHEL/Fedora”">​</a></h3><p>Tor 包是 EPEL 倉庫的一部分，所以如果我們安裝了 EPEL 倉庫，我們可以直接使用 <code>yum</code> 來安裝 Tor。如果你需要在您的系統上安裝 EPEL 倉庫，請使用下列適當的命令（基於操作系統和體系結構）：</p><p>RHEL/CentOS 7：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo rpm -Uvh https://dl.fedoraproject.org/pub/epel/7/x86_64/e/epel-release-7-11.noarch.rpm</span></span></code></pre></div><p>RHEL/CentOS 6 (64 位)：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo rpm -Uvh http://download.fedoraproject.org/pub/epel/6/x86_64/epel-release-6-8.noarch.rpm</span></span></code></pre></div><p>RHEL/CentOS 6 (32 位)：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo rpm -Uvh http://dl.fedoraproject.org/pub/epel/6/i386/epel-release-6-8.noarch.rpm</span></span></code></pre></div><p>安裝完成後，我們可以用下面的命令安裝 Tor 瀏覽器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install tor</span></span></code></pre></div><h3 id="ubuntu" tabindex="-1">Ubuntu <a class="header-anchor" href="#ubuntu" aria-label="Permalink to “Ubuntu”">​</a></h3><p>為了在 Ubuntu 機器上安裝 Tor 網絡，我們需要添加官方 Tor 倉庫。我們需要將倉庫信息添加到 <code>/etc/apt/sources.list</code> 中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nano /etc/apt/sources.list</span></span></code></pre></div><p>現在根據你的操作系統添加下面的倉庫信息：</p><p>Ubuntu 16.04：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>deb http://deb.torproject.org/torproject.org xenial main</span></span>
<span class="line"><span>deb-src http://deb.torproject.org/torproject.org xenial main</span></span></code></pre></div><p>Ubuntu 14.04</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>deb http://deb.torproject.org/torproject.org trusty main</span></span>
<span class="line"><span>deb-src http://deb.torproject.org/torproject.org trusty main</span></span></code></pre></div><p>接下來打開終端並執行以下兩個命令添加用於簽名軟件包的 gpg 密鑰：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg -keyserver keys.gnupg.net -recv A3C4F0F979CAA22CDBA8F512EE8CBC9E886DDD89</span></span>
<span class="line"><span>$ gpg -export A3C4F0F979CAA22CDBA8F512EE8CBC9E886DDD89 | sudo apt-key add -</span></span></code></pre></div><p>現在運行更新並安裝 Tor 網絡：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get update</span></span>
<span class="line"><span>$ sudo apt-get install tor deb.torproject.org-keyring</span></span></code></pre></div><h3 id="debian" tabindex="-1">Debian <a class="header-anchor" href="#debian" aria-label="Permalink to “Debian”">​</a></h3><p>我們可以無需添加任何倉庫在 Debian 上安裝 Tor 網絡。只要打開終端並以 root 身份執行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ apt install tor</span></span></code></pre></div><h3 id="tor-配置" tabindex="-1">Tor 配置 <a class="header-anchor" href="#tor-配置" aria-label="Permalink to “Tor 配置”">​</a></h3>`,26)),e("p",null,[t[3]||(t[3]=s("如果你最終目的只是為了保護互聯網瀏覽，而沒有其他要求，直接使用 Tor 更好，但是如果你需要保護即時通信、IRC、Jabber 等程序，則需要配置這些應用程序進行安全通信。但在做之前，讓我們先看看",-1)),a(i,{href:"https://www.torproject.org/download/download.html.en#warning"},{default:n(()=>[...t[2]||(t[2]=[s("Tor 網站上提到的警告",-1)])]),_:1}),t[4]||(t[4]=s("。",-1))]),t[22]||(t[22]=l('<ul><li>不要大流量使用 Tor</li><li>不要在 Tor 中使用任何瀏覽器插件</li><li>只使用 HTTPS 版本的網站</li><li>不要在線打開通過 Tor 下載的任何文檔。</li><li>儘可能使用 Tor 橋</li></ul><p>現在配置程序來使用 Tor，例如 jabber。首先選擇 “SOCKS代理” 而不是使用 HTTP 代理，並使用端口號 <code>9050</code>，或者也可以使用端口 9150（Tor 瀏覽器使用）。</p><p><img src="https://i0.wp.com/linuxtechlab.com/wp-content/uploads/2017/12/tor-1-compressor.png?resize=333%2C240" alt="install tor network"></p><p>你也可以配置 Firefox 瀏覽器使用 Tor 網絡。打開 Firefox 瀏覽器，在“常規”選項卡的“首選項”中進入“網絡代理”設置，並按以下步驟輸入代理：</p><p><img src="https://i1.wp.com/linuxtechlab.com/wp-content/uploads/2017/12/tor-2-compressor.png?resize=730%2C640" alt="install tor network"></p><p>現在你可以在 Firefox 中使用 Tor 網絡完全匿名訪問了。</p><p>這就是我們如何安裝 Tor 網絡並使用 Tor 瀏覽互聯網的教程。請在下面的評論欄中提出你的問題和建議。</p><hr>',8)),e("p",null,[t[6]||(t[6]=s("via: ",-1)),a(i,{href:"http://linuxtechlab.com/learn-install-tor-network-linux/"},{default:n(()=>[...t[5]||(t[5]=[s("http://linuxtechlab.com/learn-install-tor-network-linux/",-1)])]),_:1})]),e("p",null,[t[10]||(t[10]=s("作者：",-1)),a(i,{href:"http://linuxtechlab.com/author/shsuain/"},{default:n(()=>[...t[7]||(t[7]=[s("Shusain",-1)])]),_:1}),t[11]||(t[11]=s(" 譯者：",-1)),a(i,{href:"https://github.com/geekpi"},{default:n(()=>[...t[8]||(t[8]=[s("geekpi",-1)])]),_:1}),t[12]||(t[12]=s(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:n(()=>[...t[9]||(t[9]=[s("wxy",-1)])]),_:1})]),e("p",null,[t[15]||(t[15]=s("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[13]||(t[13]=[s("LCTT",-1)])]),_:1}),t[16]||(t[16]=s(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:n(()=>[...t[14]||(t[14]=[s("Linux中國",-1)])]),_:1}),t[17]||(t[17]=s(" 榮譽推出",-1))])])}const C=o(u,[["render",h]]);export{x as __pageData,C as default};
